#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
#include <utility>
#include <cstring>
#include <cctype>
using namespace std;

#define pii pair<int,int>
#define fi first
#define se second
#define mp make_pair
#define pb push_back

const int MAX_N = 11;
const int INF = 1000000000;
const int MAX_VERTS = 2 * MAX_N * MAX_N;

struct Arc {
    int v;
    int cap;
    int f;
    int rev;
    Arc() : v(0), cap(0), f(0), rev(0) {}
    Arc(int v2, int c, int f2, int r) : v(v2), cap(c), f(f2), rev(r) {}
};

vector<Arc> adj[MAX_VERTS];
int dist[MAX_VERTS];
int idx[MAX_VERTS];
int source, sink, N;
queue<int> Q;

void connect(int u, int v, int c) {
    adj[u].pb(Arc(v, c, 0, adj[v].size()));
    adj[v].pb(Arc(u, 0, 0, adj[u].size()-1));
    adj[u].back().rev = adj[v].size()-1;
    adj[v].back().rev = adj[u].size()-1;
}

bool levelize() {
    fill(dist, dist + sink + 1, INF);
    dist[source] = 0;
    Q.push(source);
    while (!Q.empty()) {
        int u = Q.front(); Q.pop();
        for (const Arc& e : adj[u]) {
            int w = e.v;
            int rc = e.cap - e.f;
            if (dist[w] == INF && rc > 0) {
                dist[w] = dist[u] + 1;
                Q.push(w);
            }
        }
    }
    return dist[sink] != INF;
}

int augment(int u, int f) {
    if (u == sink) return f;
    for (int& i = idx[u]; i < (int)adj[u].size(); ++i) {
        Arc& e = adj[u][i];
        int v = e.v;
        int rc = e.cap - e.f;
        int flow;
        if (dist[v] == dist[u] + 1 && rc > 0 && (flow = augment(v, min(f, rc)))) {
            e.f += flow;
            adj[v][e.rev].f -= flow;
            return flow;
        }
    }
    return 0;
}

int flow() {
    int tot = 0;
    while (levelize()) {
        memset(idx, 0, sizeof(idx));
        int delta;
        while ((delta = augment(source, INF))) {
            tot += delta;
        }
    }
    return tot;
}

queue<pii> Q2;
const int X[4] = {-1, 1, 0, 0};
const int Y[4] = {0, 0, -1, 1};
int D[MAX_N][MAX_N][MAX_N][MAX_N], T;
char A[MAX_N][MAX_N], B[MAX_N][MAX_N];
pii avoid;

bool safe(pii p) {
    int x = p.fi, y = p.se;
    return x >= 0 && x < N && y >= 0 && y < N && A[x][y] != 'Y' && A[x][y] != 'Z';
}

void bfs_dist(int sx, int sy) {
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            D[sx][sy][i][j] = INF;
        }
    }
    D[sx][sy][sx][sy] = 0;
    Q2.push(mp(sx, sy));
    while (!Q2.empty()) {
        pii p = Q2.front(); Q2.pop();
        if (D[sx][sy][p.fi][p.se] == D[avoid.fi][avoid.se][p.fi][p.se] && (avoid.fi != sx || avoid.se != sy)) continue;
        for (int k = 0; k < 4; ++k) {
            pii np = mp(p.fi + X[k], p.se + Y[k]);
            if (safe(np) && D[sx][sy][np.fi][np.se] == INF && D[sx][sy][p.fi][p.se] + 1 <= D[avoid.fi][avoid.se][np.fi][np.se]) {
                D[sx][sy][np.fi][np.se] = D[sx][sy][p.fi][p.se] + 1;
                Q2.push(np);
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> N >> T;
    int px, py;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> A[i][j];
            if (A[i][j] == 'Z') { px = i; py = j; }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            cin >> B[i][j];
        }
    }
    avoid = mp(px, py);
    bfs_dist(px, py);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            D[avoid.fi][avoid.se][i][j] = min(D[avoid.fi][avoid.se][i][j], T);
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (safe(mp(i, j))) bfs_dist(i, j);
        }
    }
    source = 0;
    sink = 2 * N * N + 1;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (A[i][j] != '0') {
                connect(source, i * N + j + 1, A[i][j] - '0');
            }
            if (B[i][j] != '0') {
                connect(i * N + j + 1 + N * N, sink, B[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            for (int i1 = 0; i1 < N; ++i1) {
                for (int j1 = 0; j1 < N; ++j1) {
                    if (safe(mp(i, j)) && safe(mp(i1, j1)) && D[i][j][i1][j1] <= D[px][py][i1][j1]) {
                        connect(i * N + j + 1, i1 * N + j1 + 1 + N * N, INF);
                    }
                }
            }
        }
    }
    cout << flow() << '\n';
    return 0;
}
